    h,w=len(g),len(g[0])
    while True:
        changed=False
        # horizontal: fill zeros strictly between two same-colored cells in a row (both sides non-zero)
        for r in range(h):
            for c in range(w):
                if o[r][c]==0:
                    lo=max((i for i in range(c) if o[r][i]!=0), default=None)
                    hi=min((i for i in range(c+1,w) if o[r][i]!=0), default=None)
                    if lo is not None and hi is not None and o[r][lo]==o[r][hi]:
                        o[r][c]=o[r][lo]; changed=True
        # vertical: each maximal run of color v extends upward through zeros until hitting a diff color or top;
        # stop extending only when blocked above by same-color cell (same color runs don't join upward unless contiguous).
        for c in range(w):
            for r in range(h-1,-1,-1):
                v=o[r][c]
                if v!=0:
                    k=r-1
                    while k>=0 and o[k][c]==0: k-=1
                    if k>=0 and o[k][c]!=v: break  # run already touches same colored cell -> nothing more to add
                    while k>=0:
                        o[k][c]=v; k-=1
                        if k>=0 and o[k][c]==0: continue
                        break
        if not changed: break
    return o
